export const RideRequest = list({
  ui: { hideCreate: true, hideDelete: true, labelField: 'requestNumber', searchFields: ['requestNumber', 'pickupLabel', 'dropoffLabel'] },
  access: lockedOperationalAccess,
  fields: {
    fleet: relationship({ ...relationFilter('Fleet'), ref: 'Fleet.rides', access: { create: () => false, update: () => false } }), rider: relationship({ ...relationFilter('User'), ref: 'User.requestedRides', access: { create: () => false, update: () => false } }), quote: relationship({ ...relationFilter('RideQuote'), ref: 'RideQuote.request', access: { create: () => false, update: () => false } }),
    requestNumber: text({ isIndexed: 'unique', validation: { isRequired: true } }), status: select({ options: ['requested', 'matching', 'matched', 'cancelled', 'expired'].map(value => ({ label: value, value })), defaultValue: 'requested' }),
    requestedFor: timestamp(), passengerCount: integer({ defaultValue: 1, validation: { min: 1, max: 50 } }), accessibilityNeeds: json({ defaultValue: {} }), riderNotes: text({ ui: { displayMode: 'textarea' } }),
    pickupLabel: text(), dropoffLabel: text(), preciseRouteEncryptedRef: text({ isFilterable: false, isOrderable: false, access: { read: denyAll } }),
    quoteSnapshot: json({ defaultValue: {} }), guestProofHash: text({ isFilterable: false, isOrderable: false, access: { read: denyAll } }), guestProofExpiresAt: timestamp(),
    matchOffers: relationship({ ...relationFilter('MatchOffer'), ref: 'MatchOffer.request', many: true, access: { create: () => false, update: () => false } }), trip: relationship({ ...relationFilter('Trip'), ref: 'Trip.request', access: { create: () => false, update: () => false } }),
    ...trackingFields,
  },
})

