export const LocationEvent = list({
  ui: { hideCreate: true, hideDelete: true, labelField: 'label', searchFields: [] },
  access: { ...lockedOperationalAccess, filter: { ...lockedOperationalAccess.filter, query: async args => {
    const scope = await lockedOperationalAccess.filter.query(args)
    return scope === false ? false : { AND: [...(scope === true ? [] : [scope]), { expiresAt: { gt: new Date().toISOString() } }] }
  } } },
  fields: {
    label: labels.locationEvent,
    trip: relationship({ ...relationFilter('Trip'), ref: 'Trip.locationEvents', access: { create: () => false, update: () => false } }), actorType: select({ options: ['driver', 'rider', 'operator', 'provider'].map(value => ({ label: value, value })) }),
    recordedAt: timestamp({ validation: { isRequired: true } }), coarseGeohash: text(), encryptedCoordinateRef: text({ isFilterable: false, isOrderable: false, access: { read: denyAll } }), accuracyMeters: integer(), providerEvidence: json({ defaultValue: {}, isFilterable: false, isOrderable: false, access: { read: denyAll } }), expiresAt: timestamp(),
    ...trackingFields,
  },
})

